-- 0001: core schema for the ingestion service and the incident agent.
-- Seed rows at the bottom are generated by generate_seed.py from the simulator's fleet.

CREATE TABLE IF NOT EXISTS sites (
    id      text PRIMARY KEY,
    region  text NOT NULL
);

CREATE TABLE IF NOT EXISTS devices (
    id           text PRIMARY KEY,
    site_id      text NOT NULL REFERENCES sites (id),
    device_type  text NOT NULL CHECK (device_type IN ('charger', 'battery', 'inverter')),
    firmware     text NOT NULL
);

CREATE INDEX IF NOT EXISTS devices_site_type_idx ON devices (site_id, device_type);

CREATE TABLE IF NOT EXISTS telemetry (
    ts          timestamptz      NOT NULL,
    device_id   text             NOT NULL REFERENCES devices (id),
    firmware    text             NOT NULL,
    status      text             NOT NULL,
    power_kw    double precision NOT NULL,
    energy_kwh  double precision NOT NULL,
    soc_pct     double precision,
    voltage_v   double precision NOT NULL,
    PRIMARY KEY (device_id, ts)
);

CREATE INDEX IF NOT EXISTS telemetry_ts_idx ON telemetry (ts DESC);

CREATE TABLE IF NOT EXISTS incidents (
    id             serial PRIMARY KEY,
    fingerprint    text        NOT NULL,
    alert_name     text        NOT NULL,
    site           text,
    device_type    text,
    severity       text        NOT NULL,
    started_at     timestamptz NOT NULL,
    resolved_at    timestamptz,
    report_md      text        NOT NULL DEFAULT '',
    actions_taken  jsonb       NOT NULL DEFAULT '[]'::jsonb,
    outcome        text
);

CREATE INDEX IF NOT EXISTS incidents_fingerprint_idx ON incidents (fingerprint, started_at DESC);

